import {
  expectCurrentImageToBe,
  findCurrentImage,
  findCurrentSlide,
  lightbox,
  expectLightboxToBeOpen,
  expectLightboxToBeClosed,
} from "./test-utils.js";

const fireWheelEvent = (element: Element, options: { deltaX?: number; deltaY?: number; ctrlKey?: boolean }) => {
  // noinspection TypeScriptValidateJSTypes
  fireEvent.wheel(element, options);
};

describe("Lightbox", () => {
  it("respects open prop", () => {
    const { rerender } = render(lightbox({ open: false }));
    expectLightboxToBeClosed();

    rerender(lightbox());
    expectLightboxToBeOpen();
  });

  it("presents basic controls", () => {
    render(lightbox());

    expectLightboxToBeOpen();
    expect(screen.queryByLabelText("Close")).toBeInTheDocument();
    expect(screen.queryByLabelText("Previous")).toBeInTheDocument();
    expect(screen.queryByLabelText("Next")).toBeInTheDocument();
  });

  it("respects index prop", () => {
    for (let i = 0; i < 3; i += 1) {
      const { unmount } = render(
        lightbox({
          slides: [{ src: "image1" }, { src: "image2" }, { src: "image3" }],
          index: i,
          carousel: { preload: 1 },
        }),
      );
      expect(findCurrentImage()).toContain(`image${i + 1}`);
      unmount();
    }
  });

  it("provides navigation buttons", () => {
    render(lightbox({ slides: [{ src: "image1" }, { src: "image2" }, { src: "image3" }] }));

    expectCurrentImageToBe("image1");

    act(() => {
      screen.getByLabelText("Next").click();
    });

    expectCurrentImageToBe("image2");

    act(() => {
      screen.getByLabelText("Previous").click();
    });
    act(() => {
      screen.getByLabelText("Previous").click();
    });

    expectCurrentImageToBe("image3");
  });

  it("supports wheel navigation", () => {
    vi.useFakeTimers();

    render(
      lightbox({
        slides: [{ src: "image1" }, { src: "image2" }, { src: "image3" }],
        carousel: { finite: true },
      }),
    );
    expectCurrentImageToBe("image1");

    const slide = findCurrentSlide()!;

    // not a swipe
    fireWheelEvent(slide, { deltaX: 1 });
    fireWheelEvent(slide, { ctrlKey: true });
    fireWheelEvent(slide, { deltaX: 100, deltaY: 200 });
    fireWheelEvent(slide, { deltaX: 500, deltaY: 1000 });
    act(vi.runAllTimers);
    expectCurrentImageToBe("image1");

    // invalid swipe
    fireWheelEvent(slide, { deltaX: -100 });
    fireWheelEvent(slide, { deltaX: -1000 });
    fireWheelEvent(slide, { deltaX: -1000 });
    act(vi.runAllTimers);
    expectCurrentImageToBe("image1");

    // insufficient swipe
    fireWheelEvent(slide, { deltaX: 50 });
    fireWheelEvent(slide, { deltaX: 100 });
    act(vi.runAllTimers);
    expectCurrentImageToBe("image1");

    // valid swipe
    fireWheelEvent(slide, { deltaX: 10 });
    fireWheelEvent(slide, { deltaX: 20 });
    fireWheelEvent(slide, { deltaX: 30 });
    fireWheelEvent(slide, { deltaX: 100 });
    fireWheelEvent(slide, { deltaX: 300 });
    fireWheelEvent(slide, { deltaX: 100 });
    act(vi.runAllTimers);
    expectCurrentImageToBe("image2");

    vi.useRealTimers();
  });
});
import * as React from "react";

import { AnimationSettings, ComponentProps, LightboxExternalProps, Node } from "./types.js";
import { parseInt } from "./utils.js";
import { LightboxDefaultProps } from "./props.js";
import { createNode, withPlugins } from "./config.js";
import {
  A11yContextProvider,
  EventsProvider,
  LightboxPropsProvider,
  LightboxStateProvider,
  TimeoutsProvider,
} from "./contexts/index.js";
import {
  CarouselModule,
  ControllerModule,
  NavigationModule,
  NoScrollModule,
  PortalModule,
  RootModule,
  ToolbarModule,
} from "./modules/index.js";

function renderNode(node: Node, props: ComponentProps): React.ReactElement {
  return React.createElement(
    node.module.component,
    { key: node.module.name, ...props },
    node.children?.map((child) => renderNode(child, props)),
  );
}

function mergeAnimation(defaultAnimation: AnimationSettings, animation: LightboxExternalProps["animation"] = {}) {
  const { easing: defaultAnimationEasing, ...restDefaultAnimation } = defaultAnimation;
  const { easing, ...restAnimation } = animation;
  return {
    easing: { ...defaultAnimationEasing, ...easing },
    ...restDefaultAnimation,
    ...restAnimation,
  };
}

/** Lightbox component */
export function Lightbox({
  carousel,
  animation,
  render,
  toolbar,
  controller,
  noScroll,
  on,
  plugins,
  slides,
  index,
  ...restProps
}: LightboxExternalProps) {
  const {
    animation: defaultAnimation,
    carousel: defaultCarousel,
    render: defaultRender,
    toolbar: defaultToolbar,
    controller: defaultController,
    noScroll: defaultNoScroll,
    on: defaultOn,
    slides: defaultSlides,
    index: defaultIndex,
    plugins: defaultPlugins,
    ...restDefaultProps
  } = LightboxDefaultProps;

  const { config, augmentation } = withPlugins(
    [
      createNode(PortalModule, [
        createNode(NoScrollModule, [
          createNode(ControllerModule, [
            createNode(CarouselModule),
            createNode(ToolbarModule),
            createNode(NavigationModule),
          ]),
        ]),
      ]),
    ],
    plugins || defaultPlugins,
  );

  const props = augmentation({
    animation: mergeAnimation(defaultAnimation, animation),
    carousel: { ...defaultCarousel, ...carousel },
    render: { ...defaultRender, ...render },
    toolbar: { ...defaultToolbar, ...toolbar },
    controller: { ...defaultController, ...controller },
    noScroll: { ...defaultNoScroll, ...noScroll },
    on: { ...defaultOn, ...on },
    ...restDefaultProps,
    ...restProps,
  });

  if (!props.open) return null;

  return (
    <LightboxPropsProvider {...props}>
      <LightboxStateProvider
        slides={slides || defaultSlides}
        // safeguard against invalid `index` prop
        index={parseInt(index || defaultIndex)}
      >
        <TimeoutsProvider>
          <EventsProvider>
            <A11yContextProvider>{renderNode(createNode(RootModule, config), props)}</A11yContextProvider>
          </EventsProvider>
        </TimeoutsProvider>
      </LightboxStateProvider>
    </LightboxPropsProvider>
  );
}
